import { createStyleContext } from "@styled-system/jsx"
import { Avatar as AvatarPrimitive } from "radix-ui"

import { recipe } from "./recipe"

const { withContext, withProvider } = createStyleContext(recipe)

export const Root = withProvider(AvatarPrimitive.Root, "root")

export const Image = withContext(AvatarPrimitive.Image, "image")

export const Fallback = withContext(AvatarPrimitive.Fallback, "fallback")

import { sva } from "@styled-system/css"

export const recipe = sva({
  slots: ["root", "image", "fallback"],
  base: {
    root: {
      position: "relative",
      display: "flex",
      h: "12",
      w: "12",
      flexShrink: "0",
      overflow: "hidden",
      rounded: "full",
    },
    image: {
      aspectRatio: "square",
      h: "full",
      w: "full",
    },
    fallback: {
      display: "flex",
      h: "full",
      w: "full",
      alignItems: "center",
      justifyContent: "center",
      rounded: "full",
      bg: "neutral",
    },
  },
})

import { cn } from "@utils/cn"
import { Avatar as AvatarPrimitive } from "radix-ui"
import {
  type ComponentPropsWithoutRef,
  type ElementRef,
  forwardRef,
} from "react"

export const Root = forwardRef<
  ElementRef<typeof AvatarPrimitive.Root>,
  ComponentPropsWithoutRef<typeof AvatarPrimitive.Root>
>(({ className, ...props }, ref) => (
  <AvatarPrimitive.Root
    ref={ref}
    className={cn(
      "relative flex size-12 shrink-0 overflow-hidden rounded-full",
      className,
    )}
    {...props}
  />
))

Root.displayName = AvatarPrimitive.Root.displayName

export const Image = forwardRef<
  ElementRef<typeof AvatarPrimitive.Image>,
  ComponentPropsWithoutRef<typeof AvatarPrimitive.Image>
>(({ className, ...props }, ref) => (
  <AvatarPrimitive.Image
    ref={ref}
    className={cn("aspect-square size-full", className)}
    {...props}
  />
))

Image.displayName = AvatarPrimitive.Image.displayName

export const Fallback = forwardRef<
  ElementRef<typeof AvatarPrimitive.Fallback>,
  ComponentPropsWithoutRef<typeof AvatarPrimitive.Fallback>
>(({ className, ...props }, ref) => (
  <AvatarPrimitive.Fallback
    ref={ref}
    className={cn(
      "flex size-full items-center justify-center rounded-full bg-neutral",
      className,
    )}
    {...props}
  />
))

Fallback.displayName = AvatarPrimitive.Fallback.displayName
